const combined = $('Document Extract PDF CAD').first().json;
const validation = $('Validate Project Context').first().json;
const context = $input.first().json;
const pdf = combined.pdf ?? {};
const cad = combined.cad ?? {};

return [{ json: {
  source: {
    pdf_file_name: combined.pdf_file_name ?? 'document.pdf',
    cad_file_name: combined.cad_file_name ?? 'drawing.dxf',
    total_pdf_pages: combined.total_pdf_pages ?? 0,
    selected_page: combined.selected_page ?? 1,
  },
  project_context: {
    context_id: context.context_id,
    enabled: context.enabled ?? false,
    start_page: combined.explanatory_note_context?.start_page ?? null,
    end_page: combined.explanatory_note_context?.end_page ?? null,
    pages_count: context.pages_count ?? 0,
    indexed_chunks: context.chunks_count ?? 0,
    vector_size: context.vector_size ?? 0,
    validation,
  },
  page: {
    page_number: combined.selected_page ?? 1,
    page_type: pdf.page_type ?? 'unknown',
    text: combined.analysis_text ?? '',
    width_points: pdf.width_points ?? 0,
    height_points: pdf.height_points ?? 0,
    image_base64: combined.combined_image_base64 ?? '',
  },
  cad: {
    original_file_name: cad.original_file_name ?? '',
    original_format: cad.original_format ?? '',
    normalized_format: cad.normalized_format ?? '',
    converted_from_dwg: cad.converted_from_dwg ?? false,
    selected_layout: cad.selected_layout ?? '',
    warnings: Array.isArray(cad.warnings) ? cad.warnings : [],
    machine_data: cad.machine_data ?? {},
    machine_context: cad.machine_context ?? '',
  },
  render: {
    mime_type: 'image/png',
    image_base64: combined.combined_image_base64 ?? '',
    pdf_image_base64: pdf.image_base64 ?? '',
    cad_image_base64: cad.image_base64 ?? '',
  },
} }];

const prepared = $('Prepare Experience Queries').item.json;
const findings = Array.isArray(prepared.findings) ? prepared.findings : [];
const results = Array.isArray($json.results) ? $json.results : [];
const experienceByFinding = {};
for (let index = 0; index < findings.length; index += 1) {
  experienceByFinding[findings[index].finding_id] = Array.isArray(results[index]?.sources) ? results[index].sources : [];
}
return { json: { findings, experience_by_finding: experienceByFinding } };

const prepared = $('Prepare Combined Context').item.json;
const understanding = $('Understand Combined Page').item.json;
const queries = $('Build Normative Queries').item.json;
const normative = $('Search Normative').item.json;
const check = $('Check Norms').item.json;
const augmentation = $('Augment Project Context').item.json;
const finalization = $json;
const findings = (finalization.findings ?? []).map((finding) => ({ ...finding, project_context_sources: augmentation.sources ?? [] }));

return { json: {
  status: 'completed',
  source_mode: 'pdf_cad',
  file_name: prepared.source.pdf_file_name,
  pdf_file_name: prepared.source.pdf_file_name,
  cad_file_name: prepared.source.cad_file_name,
  total_pages: prepared.source.total_pdf_pages,
  selected_pages: [prepared.source.selected_page],
  analyzed_pages: 1,
  findings_count: findings.length,
  summary: findings.length ? `Найдено замечаний: ${findings.length}.` : 'Замечания по выбранному PDF + CAD листу не найдены.',
  findings,
  render: prepared.render,
  cad: prepared.cad,
  explanatory_note_context: prepared.project_context,
  page: {
    page_number: prepared.page.page_number,
    heuristic_page_type: prepared.page.page_type,
    width_points: prepared.page.width_points,
    height_points: prepared.page.height_points,
    facts: understanding.facts ?? {},
    normative_queries: queries.queries ?? [],
    normative_sources: normative.sources ?? [],
    normative_check: { summary: check.summary ?? '', findings: check.findings ?? [], metrics: check.metrics ?? {} },
    project_context_sources: augmentation.sources ?? [],
  },
  pipeline: ['combined_document_extract','explanatory_note_validation','temporary_project_context_index','page_understanding','project_context_retrieval','normative_queries','normative_search','normative_check','experience_search','finalization','project_context_cleanup'],
  limitations: ['Контекст ПЗ является контекстом проекта, а не нормативным доказательством.', 'Точное расположение finding на изображении будет добавлено на этапе визуализации.'],
} };
